'use strict';
const P=ReceiptParser,$=id=>document.getElementById(id),C=P.CATEGORIES;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
function readSettings(){let v={};try{v=JSON.parse(typeof Native!=='undefined'?Native.settings():localStorage.getItem('baozhang-settings')||'{}')||{};}catch(_){}return {language:v.language==='en'?'en':'zh',currency:P.normalizeCurrency(v.currency)};}
const S={tab:'calendar',settings:readSettings(),receipts:[],days:{},draft:null,month:today().slice(0,7),selectedDay:today(),listCategory:'all',search:'',exportCategory:null,from:'',to:'',selected:new Set(),warnings:[],parsed:null,busy:false,modal:null,demo:typeof Native==='undefined'};
const lang=()=>S.settings.language,t=(zh,params)=>I18N.t(lang(),zh,params),tr=message=>I18N.translate(lang(),message),catName=c=>P.categoryLabel(c,lang()),gbp=n=>P.formatMoney(n,'GBP');
// Allowance reminders exist in pounds only (user-confirmed); choosing euros hides them.
const limitsOn=()=>S.settings.currency==='GBP',draftCurrency=r=>P.normalizeCurrency(r&&r.currency||S.settings.currency);
const ICONS={receipt:'<path d="M6 3h12v19l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h6M9 16h3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18M7 14h2m4 0h2m-8 4h2"/>',folder:'<path d="M3 7V5h7l2 3h9v12H3z"/><path d="M3 12h18"/>',export:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',train:'<rect x="5" y="3" width="14" height="15" rx="4"/><path d="M5 10h14M8 18l-2 3m10-3 2 3M9 14h.01M15 14h.01"/>',travel:'<path d="M3 15h18M5 15v3h14v-3M8 15V8h8v7M6 8h12M10 5h4M9 18l-2 3m8-3 2 3"/>',food:'<path d="M5 3v7m3-7v7M2 3v7h6m-3 0v11M16 3c-3 3-4 8 0 9h3V3h-3zm3 9v9"/>',box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4zM3 7l9 4 9-4M12 11v11M8 5l9 4"/>',client:'<path d="M4 9h13v5a6 6 0 0 1-12 0V9m13 1h2a3 3 0 0 1 0 6h-2M3 21h17M8 3v3m5-3v3"/>',plus:'<path d="M12 5v14M5 12h14"/>',camera:'<path d="M3 8h4l2-3h6l2 3h4v12H3z"/><circle cx="12" cy="14" r="4"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',back:'<path d="m14 5-7 7 7 7"/>'};
const catIcons=['train','travel','food','box','client'],catDescriptions=['地铁、公交与市内出行','火车、长途交通与跨城出行','出差期间的餐饮发票','办公耗材与用品','客户餐饮与接待费用'];
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.receipt}</svg>`;}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function amount(n,currency){return P.formatMoney(n,currency);}
function sum(rows){return P.formatTotals(P.totals(rows),S.settings.currency);}
function typeName(type){return t({business:'出差',office:'办公',holiday:'休假'}[type]||'未标记');}
function catIcon(category){return catIcons[C.indexOf(category)]||'receipt';}
function modal(title,body,type){S.modal=type;$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalBackdrop').classList.remove('hidden');$('modalBackdrop').scrollTop=0;}
function closeModal(){if(S.viewer){closePreview();return;}if(S.modal==='editor'){if(!confirm(t('关闭核对页面？草稿仍会保留，可稍后继续。')))return;persistFields();}S.modal=null;$('modalBackdrop').classList.add('hidden');}
function hideModal(){S.modal=null;$('modalBackdrop').classList.add('hidden');}
function toast(text){$('toast').textContent=text;$('toast').classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.add('hidden'),4500);}
function busy(text){S.busy=true;$('busyText').textContent=text;$('busy').classList.remove('hidden');}
function idle(){S.busy=false;$('busy').classList.add('hidden');}
function call(method,...args){if(S.demo)return demoCall(method,...args);try{Native[method](...args);}catch(e){idle();toast(t('无法调用手机功能：{message}',{message:e.message}));}}
function nav(){const tabs=[['calendar','calendar','日历'],['receipts','folder','发票'],['export','export','导出'],['archive','folder','归档']];$('bottomNav').innerHTML=tabs.map(([tab,i,label])=>`<button data-tab="${tab}" class="${S.tab===tab?'active':''}" aria-current="${S.tab===tab?'page':'false'}">${icon(i)}${t(label)}</button>`).join('');}
function render(){nav();if(S.tab==='calendar')renderCalendar();else if(S.tab==='receipts')renderReceipts();else if(S.tab==='archive')renderArchive();else renderExport();}
function receiptCard(r,select=false){const selected=S.selected.has(r.id),money=amount(r.amountMinor,r.currency);return `<article class="receipt" data-${select?'toggle':'receipt'}="${esc(r.id)}" tabindex="0" role="button" aria-label="${esc(r.merchant)} ${money}${select?t(selected?'，已选中':'，未选中'):''}">${select?`<input class="check" type="checkbox" aria-label="${esc(t('选择{name}',{name:r.merchant}))}" data-checkbox="${esc(r.id)}" ${selected?'checked':''}>`:''}<span class="receipt-icon">${icon(catIcon(r.category))}</span><div class="receipt-content"><strong>${esc(r.merchant)}</strong><small>${esc(catName(r.category))}${r.archivedAt?t(' · 已归档'):''} · ${esc(I18N.shortDate(lang(),r.date))}${r.location?' · '+esc(r.location):''}</small></div><div class="receipt-money">${money}<small>${t('{n} 个附件',{n:r.documents.length})}</small></div></article>`;}
function empty(text){return `<div class="empty-state">${icon('receipt')}<p>${text}</p></div>`;}
function draftBanner(){return S.draft?`<button class="notice" id="resumeDraft" style="width:100%;text-align:left;border:0">${t('有一张未完成的发票，点击继续核对 →')}</button>`:'';}
function cityForDate(date,rows=S.receipts){if(!P.validDate(date))return null;const month=date.slice(0,7);return P.monthlyTransportBudgets(rows).find(t=>t.month===month)||{month,totalMinor:0,limitMinor:P.CITY_MONTHLY_LIMIT_MINOR,remainingMinor:P.CITY_MONTHLY_LIMIT_MINOR,overMinor:0};}
function cityReminder(c){return c.overMinor?t('本月市内交通超出 {amount}，请核对',{amount:gbp(c.overMinor)}):c.remainingMinor?t('本月市内交通还有 {amount} 额度未使用',{amount:gbp(c.remainingMinor)}):t('本月市内交通额度已用满');}
function cityCard(c,preview=false){return '<div class="trip-budget city-budget '+(c.overMinor?'over':c.remainingMinor?'under':'full')+'" role="status"><strong>'+t('{month} · 市内交通',{month:I18N.monthTitle(lang(),Number(c.month.slice(0,4)),Number(c.month.slice(5,7)))})+'</strong><p>'+t('自然月额度 {amount}',{amount:gbp(c.limitMinor)})+'</p><p>'+t(preview?'本张确认后的预计全月市内交通 {amount}':'全月已确认市内交通 {amount}',{amount:gbp(c.totalMinor)})+'</p><p class="budget-reminder">'+cityReminder(c)+'</p><small>'+t('按全月全部已确认发票累计，包含归档发票；超出仍可保存和导出。')+'</small></div>';}
function exportNamesHint(category,from,to){try{const names=P.exportNames(category,from,to,lang());return '<p class="export-name-hint">'+t('将生成：')+esc(names.pdf)+'<br>'+esc(names.xlsx)+'</p>';}catch{return '';}}
// Trip allowances are in the trip country's currency: pounds in the UK, euros elsewhere.
const countryOf=date=>S.countries?.[date]||'GB',countryName=code=>P.countryLabel(code,lang()),currencyName=c=>t(c==='EUR'?'欧元 EUR':'英镑 GBP');
function inheritCountry(date){const before=new Date(Date.parse(date+'T00:00:00Z')-86400000).toISOString().slice(0,10);return S.countries?.[date]||(S.days[before]==='business'?countryOf(before):'GB');}
function countryOptions(selected){return P.TRIP_COUNTRIES.map(c=>`<option value="${c.code}" ${c.code===selected?'selected':''}>${esc(countryName(c.code))} · ${t('每天 {daily}',{daily:P.formatMoney(c.dailyMinor,c.currency)})}</option>`).join('');}
function budgetReminder(b){const m=n=>P.formatMoney(n,b.currency);return b.overMinor?t('连续出差餐补超出 {amount}，请核对',{amount:m(b.overMinor)}):b.remainingMinor?t('还有 {amount} 额度未使用，请核对餐补票据是否已录入完整',{amount:m(b.remainingMinor)}):t('本段餐补额度已用满');}
function budgetCard(b,preview=false){const m=n=>P.formatMoney(n,b.currency),daily=m(b.dailyMinor),country=esc(countryName(b.country));return `<div class="trip-budget ${b.overMinor?'over':b.remainingMinor?'under':'full'}" role="status" data-country="${b.country}"><strong>${t('{from} 至 {to} · {country} · 出差 {n} 天',{from:I18N.fmtDate(lang(),b.from),to:I18N.fmtDate(lang(),b.to),n:b.days,country})}</strong><p>${t('餐补总额度 {amount}（{country}每天 {daily}，可跨天使用）',{amount:m(b.limitMinor),daily,country})}</p><p>${t(preview?'本张确认后的预计餐补 {amount}':'整段已确认餐补 {amount}',{amount:m(b.totalMinor)})}</p><p class="budget-reminder">${budgetReminder(b)}</p>${b.otherCurrencyIds.length?`<p class="budget-reminder">${t('另有 {n} 张其他货币的餐补发票在这段出差内，未计入额度，请核对',{n:b.otherCurrencyIds.length})}</p>`:''}<small>${b.overMinor?t('额度已超出，请核对。仍可保存和导出。'):t('按整段累计，单日超过 {daily} 不会单独报超额。',{daily})}</small></div>`;}
function budgetForDate(date,rows=S.receipts){return P.tripBudgets(rows,S.days,S.countries).find(t=>date>=t.from&&date<=t.to);}
function exportBudget(rows){if(!rows.length)return '';if(S.exportCategory===C[0]){const pounds=rows.filter(r=>P.currencyOf(r)==='GBP');if(!pounds.length||!limitsOn())return '';return P.monthlyTransportBudgets(S.receipts).filter(c=>pounds.some(r=>r.date.slice(0,7)===c.month)).map(c=>cityCard(c)).join('');}if(S.exportCategory!==C[2])return '';const trips=P.tripBudgets(S.receipts,S.days,S.countries).filter(b=>rows.some(r=>r.date>=b.from&&r.date<=b.to)),unmarked=rows.filter(r=>S.days[r.date]!=='business').length;return trips.map(b=>budgetCard(b)).join('')+(unmarked?`<div class="warning">${t('{n} 张所选餐补发票的日期未标记出差，未计入连续出差额度，请核对日程。',{n:unmarked})}</div>`:'');}
function savedMessage(message,saved){const on=limitsOn()&&saved.currency==='GBP',meal=saved.category===C[2]?budgetForDate(saved.date):null,trip=meal&&meal.currency===saved.currency?meal:null,city=on&&saved.category===C[0]?cityForDate(saved.date):null;return tr(message)+(trip?t('；')+budgetReminder(trip):city?t('；')+cityReminder(city):'');}
function duplicateHint(draft){const duplicates=P.receiptDuplicates(draft,S.receipts),matches=duplicates.matches;
 if(!matches.length&&!duplicates.repeatedAttachments)return '';
 const exact=matches.some(r=>r.kind==='file');return `<div class="duplicate-warning" role="alert"><strong>${t(exact?'检测到重复原件':matches.length?'检测到疑似重复发票':'当前草稿有重复附件')}</strong><p>${t(exact?'此图片/PDF 的文件内容与已有发票相同。':matches.length?'日期、商家和金额与已有记录相同，可能是重复报账，也可能是同日不同消费，请对照原件。':'当前草稿内出现相同文件内容，请检查附件。')}</p>${duplicates.repeatedAttachments?`<p>${t('草稿内还有 {n} 个重复附件。',{n:duplicates.repeatedAttachments})}</p>`:''}${matches.slice(0,3).map(r=>`<p class="duplicate-match">${esc(I18N.fmtDate(lang(),r.date))} · ${esc(r.merchant)} · ${amount(r.amountMinor,S.receipts.find(o=>o.id===r.id)?.currency)} · ${t(r.kind==='file'?'相同原件':'信息相同')}</p>`).join('')}<small>${t('原件已保留。保存前会再次提示，由你决定是否保留。')}</small></div>`;}
function updateEditorHints(){if(S.modal!=='editor'||!$('editorBudget'))return;const fields=fieldData(),draft={...S.draft,...fields};$('duplicateHint').innerHTML=duplicateHint(draft);$('editorBudget').innerHTML='';if(fields.category===C[0]&&P.validDate(fields.date)){if(!limitsOn()||fields.currency!=='GBP')return;let amountMinor;try{amountMinor=P.minor(fields.amount);}catch{return;}const rows=S.receipts.filter(r=>!draft.id||r.id!==draft.id).concat({id:draft.id,date:fields.date,category:C[0],amountMinor,confirmed:true});$('editorBudget').innerHTML=cityCard(cityForDate(fields.date,rows),true);return;}if(fields.category!==C[2]||!P.validDate(fields.date))return;let amountMinor;try{amountMinor=P.minor(fields.amount);}catch{return;}const rows=S.receipts.filter(r=>!draft.id||r.id!==draft.id).concat({id:draft.id,date:fields.date,category:C[2],amountMinor,currency:fields.currency,confirmed:true}),trip=budgetForDate(fields.date,rows);$('editorBudget').innerHTML=trip?(trip.currency!==fields.currency?`<div class="warning">${t('这天在{country}出差，餐补按{currency}计算；这张发票是{own}，不计入额度。',{country:esc(countryName(trip.country)),currency:currencyName(trip.currency),own:currencyName(fields.currency)})}</div>`:'')+budgetCard(trip,true):`<div class="notice">${t('此日期未标记为出差，餐补额度暂未计算。可在日历中设置出差日期。')}</div>`;}
// Home summary: the period/category shown in the headline total is chosen by the user and remembered on this device.
function summaryPrefs(){try{const v=JSON.parse(localStorage.getItem('bz-summary')||'{}');return {period:v.period||'thisMonth',category:v.category||'all'};}catch(_){return {period:'thisMonth',category:'all'};}}
function summaryPicker(sm){return `<div class="summary-pick"><select id="summaryPeriod" aria-label="${t('统计时间范围')}">${P.SUMMARY_PERIODS.map(([k,l])=>`<option value="${k}" ${sm.period===k?'selected':''}>${t(l)}</option>`).join('')}</select><select id="summaryCategory" aria-label="${t('统计费用类别')}"><option value="all">${t('全部类别')}</option>${C.map(c=>`<option value="${esc(c)}" ${sm.category===c?'selected':''}>${esc(catName(c))}</option>`).join('')}</select></div>`;}
document.addEventListener('change',e=>{const id=e.target&&e.target.id;if(id!=='summaryPeriod'&&id!=='summaryCategory')return;const p=summaryPrefs();p[id==='summaryPeriod'?'period':'category']=e.target.value;try{localStorage.setItem('bz-summary',JSON.stringify(p));}catch(_){}renderCalendar();});
function renderCalendar(){
 const [y,m]=S.month.split('-').map(Number),monthRows=S.receipts.filter(r=>r.date.startsWith(S.month)),sm=P.summarize(S.receipts,{...summaryPrefs(),today:today(),viewMonth:S.month,lang:lang(),currency:S.settings.currency});
 const daysIn=new Date(y,m,0).getDate(),offset=(new Date(y,m-1,1).getDay()+6)%7;
 const dates=S.receipts.reduce((o,r)=>(o[r.date]=(o[r.date]||0)+1,o),{});
 let grid='<div class="day empty"></div>'.repeat(offset);
 for(let day=1;day<=daysIn;day++){const key=`${S.month}-${String(day).padStart(2,'0')}`,type=S.days[key]||'',count=dates[key]||0;grid+=`<button class="day ${type} ${key===S.selectedDay?'selected':''} ${key===today()?'today':''}" data-day="${key}" aria-label="${esc(I18N.fmtDate(lang(),key))} ${typeName(type)} ${t('{n} 张发票',{n:count})}"><span class="num">${day}</span><span class="type">${type?typeName(type)+(type==='business'&&countryOf(key)!=='GB'?' '+countryOf(key):''):'　'}</span><span class="count">${count?t('{n} 张',{n:count}):'　'}</span></button>`;}
 const picked=S.receipts.filter(r=>r.date===S.selectedDay),type=S.days[S.selectedDay]||'unmarked';
 const heroList=P.CURRENCIES.filter(c=>sm.totals[c]),heroTotal=(heroList.length?heroList:[S.settings.currency]).map(c=>{const v=P.formatMoney(sm.totals[c]||0,c);return `<span>${v[0]}</span>${v.slice(1)}`;}).join(' + ');
 $('main').innerHTML=`${draftBanner()}<section class="hero"><div class="hero-line"><span class="eyebrow">${esc(sm.label)} · ${esc(sm.categoryLabel)}</span><span class="hero-badge">${t('{n} 张发票',{n:sm.count})}</span></div>${summaryPicker(sm)}<div class="hero-line"><div><h1>${heroTotal}</h1><p>${t('已保存发票合计')}</p></div><button id="addReceipt">${icon('plus')}${t('添加发票')}</button></div></section><section><div class="section-title"><h2>${t('我的日历')}</h2><button class="subtle-link" id="markDay">${t('标记出差 / 办公 / 休假')}</button></div><div class="calendar"><div class="month-head"><button id="prevMonth" aria-label="${t('上个月')}">‹</button><strong>${I18N.monthTitle(lang(),y,m)}</strong><button id="nextMonth" aria-label="${t('下个月')}">›</button></div><div class="weekdays">${I18N.weekdays(lang()).map(s=>`<span>${s}</span>`).join('')}</div><div class="calendar-grid">${grid}</div><div class="legend"><span><i class="dot business"></i>${t('出差')}</span><span><i class="dot office"></i>${t('办公')}</span><span><i class="dot holiday"></i>${t('休假')}</span></div></div></section><div class="section-title"><h2>${I18N.dayTitle(lang(),Number(S.selectedDay.slice(5,7)),Number(S.selectedDay.slice(8)))}<span class="day-status ${type}">${type==='business'?t('出差 · {country}',{country:esc(countryName(countryOf(S.selectedDay)))}):typeName(type)}</span></h2><button class="subtle-link" id="addForDay">${t('添加发票')}</button></div>${budgetForDate(S.selectedDay)?budgetCard(budgetForDate(S.selectedDay)):''}${limitsOn()&&P.monthlyTransportBudgets(S.receipts).some(c=>c.month===S.selectedDay.slice(0,7))?cityCard(cityForDate(S.selectedDay)):''}${picked.length?picked.map(r=>receiptCard(r)).join(''):empty(t('这一天还没有保存发票<br>拍照或导入，让费用有迹可循'))}<p class="privacy-note">${t('日期状态由你标记 · 金额按发票记录的货币显示，不做换算')}</p>`;
}
function monthChange(n){let [y,m]=S.month.split('-').map(Number);const date=new Date(y,m-1+n,1);S.month=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;S.selectedDay=S.month===today().slice(0,7)?today():S.month+'-01';render();}
// "Am I travelling, where, and for how many days": the day count and the end date stay in step.
function showMark(){modal(t('标记日期状态'),`<p class="page-sub">${t('标记一天或一段时间。已有发票的费用分类不受影响。')}</p><label class="field"><span>${t('日期状态')}</span><select id="markType"><option value="business">${t('绿色 · 出差')}</option><option value="office">${t('红色 · 办公')}</option><option value="holiday">${t('蓝色 · 休假')}</option><option value="">${t('清除标记')}</option></select></label><label class="field" id="markCountryField"><span>${t('出差国家')}</span><select id="markCountry">${countryOptions(inheritCountry(S.selectedDay))}</select></label><div class="fields-row"><label class="field"><span>${t('开始日期')}</span><input type="date" id="markFrom" value="${S.selectedDay}"></label><label class="field"><span>${t('结束日期')}</span><input type="date" id="markTo" value="${S.selectedDay}"></label></div><label class="field"><span>${t('天数')}</span><input type="number" id="markDays" min="1" max="731" step="1" inputmode="numeric" value="1"></label><p class="notice" id="markDaily"></p><button class="primary" id="saveMark">${t('保存日期状态')}</button>`,'mark');$('markType').value=S.days[S.selectedDay]||'business';markTypeChanged();}
function markTypeChanged(){const trip=$('markType').value==='business',c=P.tripCountry($('markCountry').value);$('markCountryField').classList.toggle('hidden',!trip);$('markDaily').classList.toggle('hidden',!trip);$('markDaily').textContent=t('{country}出差每天餐补上限 {daily}，按{currency}计算',{country:countryName(c.code),daily:P.formatMoney(c.dailyMinor,c.currency),currency:currencyName(c.currency)});}
function markRangeChanged(){const f=$('markFrom').value,to=$('markTo').value;$('markDays').value=P.validDate(f)&&P.validDate(to)&&to>=f?Math.round((Date.parse(to)-Date.parse(f))/86400000)+1:'';}
function markDaysChanged(){const n=Number($('markDays').value),f=$('markFrom').value;if(P.validDate(f)&&Number.isInteger(n)&&n>=1&&n<=731)$('markTo').value=new Date(Date.parse(f+'T00:00:00Z')+(n-1)*86400000).toISOString().slice(0,10);}
// A date on a marked trip day switches the draft to that country's currency (the user can change it back).
function followTrip(){const fields=fieldData(),currency=P.tripCurrencyOn(fields.date,S.days,S.countries);if(!currency||currency===fields.currency)return;Object.assign(S.draft,fields,{currency});reparseCurrency();showEditor();persistFields();toast(t('这天在{country}出差，已改为按{currency}记录',{country:countryName(countryOf(fields.date)),currency:currencyName(currency)}));}
function categoryTiles(action){return C.map((c,i)=>{const rows=S.receipts.filter(r=>r.category===c);return `<button class="category-tile ${S.newCategory===c&&action==='choose'?'chosen':''}" data-${action}="${i}"><span class="receipt-icon">${icon(catIcons[i])}</span><span><strong>${esc(catName(c))}</strong><small>${action==='exportcat'?t('{n} 张发票',{n:rows.length})+' · '+sum(rows):t(catDescriptions[i])}</small></span><span class="arrow">${icon('chevron')}</span></button>`;}).join('');}
function showNew(){if(S.draft){showEditor();return;}S.newCategory=null;modal(t('添加发票'),`<span class="step">${t('01 / 先选择费用来源')}</span><p class="page-sub">${t('可一次选择多张图片或多个 PDF，按顺序逐张核对。每个文件记为一张发票，多页发票可追加附件。')}</p><div id="newCats">${categoryTiles('choose')}</div><div class="button-row"><button class="primary" id="captureNew" disabled>${icon('camera')}${t('拍照扫描')}</button><button class="secondary" id="importNew" disabled>${icon('folder')}${t('批量导入图片 / PDF')}</button></div><p class="privacy-note">${t('导入时可长按多选 · 每批最多 30 张 · 逐张确认后保存')}</p>`,'new');}
function startCapture(kind,append){const cat=append?S.draft.category:S.newCategory;if(!cat)return toast(t('请先选择费用种类'));if(append)persistFields();hideModal();busy(t(kind==='capture'?'正在打开相机…':'正在打开文件选择器…'));call(kind,cat,append);}
function fieldData(){return {date:$('editDate').value,amount:$('editAmount').value,merchant:$('editMerchant').value.trim(),location:$('editLocation').value.trim(),category:$('editCategory').value,currency:$('editCurrency').value,note:$('editNote').value,confirmed:$('editConfirmed').checked};}
// Changing a receipt's currency re-reads its OCR text under that currency's rules; a typed amount is kept.
function reparseCurrency(){if(!S.draft.ocr)return;const p=P.parse(S.draft.ocr,{currency:draftCurrency(S.draft)});S.parsed=p;S.warnings=[...new Set([...p.warnings,...(S.extraWarnings||[])])];if(!S.draft.amount&&p.amount)S.draft.amount=p.amount;}
function persistFields(){if(S.modal!=='editor')return;const f=fieldData();Object.assign(S.draft,f);call('updateDraft',JSON.stringify(f));updateEditorHints();}
function attachments(r,editable){return `<div class="attachments">${r.documents.map((d,i)=>`<div class="attachment"><button class="attachment-preview" data-open="${i}" data-owner="${editable?'draft':esc(r.id)}" aria-label="${t('在软件内查看发票附件{n}',{n:i+1})}"><img src="${S.demo?demoPreview(d):'/preview/'+encodeURIComponent(d.name)+(d.crop?'?v='+encodeURIComponent(JSON.stringify(d.crop.quad).length+'-'+(d.crop.rotate||0)+'-'+d.crop.quad.flat().join('').slice(0,24)):'')}" alt="${t('发票附件{n}预览',{n:i+1})}" loading="lazy"></button>${editable?`<button class="remove" data-remove="${i}" aria-label="${t('移除此附件')}">${t('移除')}</button>`:''}${editable&&!S.demo&&String(d.mime||'').startsWith('image/')?`<button class="crop-button" data-crop="${i}">${t(d.crop?'调整裁剪':'裁剪 / 矫正')}</button>`:''}<button data-open="${i}" data-owner="${editable?'draft':esc(r.id)}">${d.mime==='application/pdf'?t('PDF · {n} 页',{n:d.pages}):t('发票图片')}${t(' · 查看原件')}</button></div>`).join('')}</div>`;}
let viewerToken=0;
function closePreview(){viewerToken++;S.viewer=null;$('receiptViewer')?.remove();}
function showPreview(doc){
 closePreview();S.viewer={doc,page:0,rotation:0,zoom:1};
 const overlay=document.createElement('section');overlay.id='receiptViewer';overlay.className='receipt-viewer';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label',t('发票原件预览'));
 overlay.innerHTML=`<header class="viewer-header"><strong>${t('发票原件')}</strong><button id="viewerClose" aria-label="${t('关闭原件预览')}">×</button></header><div id="viewerSurface" class="viewer-surface"><canvas id="viewerCanvas"></canvas><p id="viewerMessage">${t('正在加载…')}</p></div><div class="viewer-tools"><div><button id="viewerRotateLeft" aria-label="${t('向左旋转')}">${t('↶ 左转')}</button><button id="viewerRotateRight" aria-label="${t('向右旋转')}">${t('↷ 右转')}</button><button id="viewerZoomOut" aria-label="${t('缩小')}">−</button><button id="viewerZoomIn" aria-label="${t('放大')}">＋</button></div><div><button id="viewerPrev">${t('上一页')}</button><span id="viewerPage"></span><button id="viewerNext">${t('下一页')}</button></div><small>${t('旋转与缩放仅用于查看，原始文件保留。')}</small></div>`;
 document.body.append(overlay);$('viewerClose').onclick=closePreview;
 $('viewerRotateLeft').onclick=()=>{S.viewer.rotation=(S.viewer.rotation+270)%360;drawPreview();};$('viewerRotateRight').onclick=()=>{S.viewer.rotation=(S.viewer.rotation+90)%360;drawPreview();};
 $('viewerZoomIn').onclick=()=>{S.viewer.zoom=Math.min(4,S.viewer.zoom+.5);drawPreview();};$('viewerZoomOut').onclick=()=>{S.viewer.zoom=Math.max(1,S.viewer.zoom-.5);drawPreview();};
 $('viewerPrev').onclick=()=>{if(S.viewer.page>0){S.viewer.page--;loadPreviewPage();}};$('viewerNext').onclick=()=>{if(S.viewer.page+1<(doc.pages||1)){S.viewer.page++;loadPreviewPage();}};
 $('viewerClose').focus();loadPreviewPage();
}
function loadPreviewPage(){
 const v=S.viewer,token=++viewerToken;v.image=null;v.zoom=1;$('viewerMessage').textContent=t('正在加载…');$('viewerCanvas').hidden=true;
 const pages=v.doc.pages||1;$('viewerPage').textContent=(v.page+1)+' / '+pages;$('viewerPrev').disabled=v.page===0;$('viewerNext').disabled=v.page+1>=pages;
 const img=new Image();img.onload=()=>{if(!S.viewer||token!==viewerToken)return;v.image=img;$('viewerMessage').textContent='';$('viewerCanvas').hidden=false;drawPreview();};img.onerror=()=>{if(token===viewerToken&&S.viewer)$('viewerMessage').textContent=t('原件暂时无法显示，请关闭后重试。');};img.src=S.demo?demoPreview(v.doc):'/preview/'+encodeURIComponent(v.doc.name)+'?page='+v.page;
}
function drawPreview(){
 const v=S.viewer;if(!v?.image)return;const c=$('viewerCanvas'),img=v.image,quarter=v.rotation%180!==0;c.width=quarter?img.naturalHeight:img.naturalWidth;c.height=quarter?img.naturalWidth:img.naturalHeight;
 const ctx=c.getContext('2d');ctx.translate(c.width/2,c.height/2);ctx.rotate(v.rotation*Math.PI/180);ctx.drawImage(img,-img.naturalWidth/2,-img.naturalHeight/2);
 const surface=$('viewerSurface'),fit=Math.min((surface.clientWidth-24)/c.width,(surface.clientHeight-24)/c.height);c.style.width=Math.max(1,c.width*fit*v.zoom)+'px';c.style.height=Math.max(1,c.height*fit*v.zoom)+'px';
}
window.addEventListener('resize',()=>{if(S.viewer)drawPreview();});
function mealMerchantChoices(category){return `<div id="mealMerchantChoices" class="meal-merchants ${category===C[2]?'':'hidden'}" role="group" aria-label="${t('餐补常用商家')}"><p>${t('餐补常用商家 · 点击填写，也可直接输入其他商家')}</p><div>${P.MEAL_MERCHANTS.map(m=>P.merchantLabel(m,lang())).map(m=>`<button type="button" data-mealmerchant="${esc(m)}">${esc(m)}</button>`).join('')}</div></div>`;}
function dateChoices(parsed){const candidates=parsed.dateCandidates.filter(c=>c.eligible).slice(0,8);return candidates.length?`<div class="date-candidates" role="group" aria-label="${t('候选费用日期')}"><p>${t('识别到的日期 · 点击填写，仍需核对')}</p><div>${candidates.map(c=>`<button type="button" data-datecandidate="${c.date}" title="${esc(c.source)}"><span>${esc(I18N.fmtDate(lang(),c.date))}</span><small>${esc(t(c.kind))}${c.corrected?t(' · 已修正'):''}</small></button>`).join('')}</div></div>`:'';}
function showEditor(){
 if(!S.draft)return;const r=S.draft,currency=draftCurrency(r),parsed=S.parsed||P.parse(r.ocr||'',{currency});
 modal(r.id?t('修改发票'):r.batchTotal?t('逐张核对 · {i} / {n}',{i:r.batchIndex,n:r.batchTotal}):t('核对这张发票'),`${r.batchTotal?'<div class="batch-progress"><strong>'+t('第 {i} / {n} 张',{i:r.batchIndex,n:r.batchTotal})+'</strong><span>'+t('还有 {n} 张待核对',{n:r.batchPending?.length||0})+'</span><p>'+t('保存当前票据后自动进入下一张。关闭后可继续本批核对。')+'</p></div>':''}${r.documents.length?attachments(r,true):empty(t('请先拍照或导入发票附件'))}<div class="button-row"><button class="secondary" id="appendCamera">${icon('camera')}${t('追加拍照')}</button><button class="secondary" id="appendFile">${icon('plus')}${t('追加附件')}</button></div><div id="smartScanStatus" class="notice scan-status ${S.smartScanning?'':'hidden'}">${S.smartScanning?t('正在自动裁剪并精细识别（约 10–30 秒），可以先核对其他内容…'):''}</div>${S.warnings.length?`<div class="warning"><ul>${S.warnings.map(w=>`<li>${esc(tr(w))}</li>`).join('')}</ul></div>`:`<div class="notice">${t('请核对费用发生日期、实付总额和商家信息。')}</div>`}<label class="field"><span>${t('费用来源')}</span><select id="editCategory">${C.map(c=>`<option value="${esc(c)}" ${r.category===c?'selected':''}>${esc(catName(c))}</option>`).join('')}</select></label><label class="field"><span>${t('货币')}</span><select id="editCurrency">${P.CURRENCIES.map(c=>`<option value="${c}" ${currency===c?'selected':''}>${t(c==='GBP'?'英镑 GBP（£）':'欧元 EUR（€）')}</option>`).join('')}</select></label><div class="fields-row"><label class="field"><span>${t('费用发生日期 *')}</span><input type="date" id="editDate" value="${esc(r.date)}" required>${dateChoices(parsed)}</label><label class="field"><span>${t('实付金额（{symbol}） *',{symbol:P.CURRENCY_SYMBOLS[currency]})}</span><input id="editAmount" type="text" inputmode="decimal" placeholder="0.00" value="${esc(r.amount)}" required><div class="candidates">${(S.parsed?.amounts||[]).map(a=>`<button data-amountcandidate="${a}">${P.CURRENCY_SYMBOLS[currency]}${a}</button>`).join('')}</div></label></div><label class="field"><span>${t('商家 / 交通运营方 *')}</span><input id="editMerchant" maxlength="200" value="${esc(r.merchant)}" placeholder="${esc(t('例如 TfL、Tesco、餐厅名称'))}">${(S.parsed?.merchants||[]).length?`<div class="date-candidates merchant-candidates" role="group" aria-label="${t('识别到的商家候选')}"><p>${t('识别到的商家 · 点击填写，仍需核对')}</p><div>${S.parsed.merchants.slice(0,4).map(m=>P.merchantLabel(m,lang())).map(m=>`<button type="button" data-merchantcandidate="${esc(m)}" aria-label="${esc(t('识别候选：{name}',{name:m}))}">${esc(m)}</button>`).join('')}</div></div>`:''}</label>${mealMerchantChoices(r.category)}<label class="field"><span>${t('所在地（选填）')}</span><input id="editLocation" maxlength="200" value="${esc(r.location)}" placeholder="${esc(t('例如 London / B&Q 门店'))}"></label><label class="field"><span>${t('备注（选填）')}</span><textarea id="editNote" maxlength="2000" placeholder="${esc(t('例如出差地点、客户名称、出行路线'))}">${esc(r.note)}</textarea></label><div id="editorBudget"></div><div id="duplicateHint"></div><details><summary>${t('查看识别出的原始文字')}</summary><div class="raw">${esc(r.ocr||t('未识别出文字，可手动填写'))}</div></details><label class="confirm-label"><input type="checkbox" class="check" id="editConfirmed">${t('我已核对日期、实付金额、商家和费用分类。')}</label><button class="primary" id="saveReceipt">${icon('check')}${t(r.batchPending?.length?'保存并核对下一张':'确认并保存')}</button><button class="subtle-link" style="width:100%;margin-top:12px;color:#a34e4e" id="discardDraft">${t('放弃这张草稿')}</button>`,'editor');updateEditorHints();
}
function showDetail(id){const r=S.receipts.find(r=>r.id===id);if(!r)return;modal(t('发票详情'),`<span class="step">${esc(catName(r.category))}</span><div class="detail-amount">${amount(r.amountMinor,r.currency)}</div><dl class="detail-grid"><dt>${t('费用日期')}</dt><dd>${esc(I18N.fmtDate(lang(),r.date))}</dd><dt>${t('商家 / 运营方')}</dt><dd>${esc(r.merchant)}</dd><dt>${t('所在地')}</dt><dd>${esc(r.location||'—')}</dd><dt>${t('备注')}</dt><dd>${esc(r.note||'—')}</dd></dl><div class="section-title"><h2 style="font-size:15px">${t('发票原件')}</h2><span class="export-count">${t('{n} 个附件',{n:r.documents.length})}</span></div>${attachments(r,false)}<div class="button-row"><button class="primary" data-edit="${esc(id)}">${t('修改信息')}</button><button class="danger" data-delete="${esc(id)}">${t('删除发票')}</button></div>`,'detail');}
function renderReceipts(){const rows=P.filter(S.receipts,{category:S.listCategory,search:S.search}).reverse();$('main').innerHTML=`${draftBanner()}<h1 class="page-heading">${t('我的发票')}</h1><p class="page-sub">${t('原件与信息一起保存，随时查看与校准')}</p><input id="receiptSearch" class="search" type="search" placeholder="${t('搜索商家、所在地或备注')}" value="${esc(S.search)}"><div class="filter-pills"><button class="pill ${S.listCategory==='all'?'active':''}" data-listcat="all">${t('全部')}</button>${C.map((c,i)=>`<button class="pill ${S.listCategory===c?'active':''}" data-listcat="${i}">${esc(catName(c))}</button>`).join('')}</div><div class="stats-line"><span>${t('{n} 张发票',{n:rows.length})}</span><strong>${sum(rows)}</strong></div>${rows.length?rows.map(r=>receiptCard(r)).join(''):empty(t('还没有符合条件的发票'))}<div class="button-row"><button class="primary" id="addReceipt">${icon('plus')}${t('添加发票')}</button></div>`;}
function exportRows(){if(!S.exportCategory)return [];return P.filter(S.receipts,{category:S.exportCategory,from:S.from,to:S.to});}
function exportChanged(){S.selected=new Set(exportRows().map(r=>r.id));renderExport();}
function renderExport(){
 if(!S.exportCategory){$('main').innerHTML=`<span class="step">${t('01 / 选择费用来源')}</span><h1 class="page-heading">${t('按类别导出')}</h1><p class="page-sub">${t('先选费用种类，再选择日期范围<br>生成一份发票 PDF 和一份 Excel 汇总表')}</p>${categoryTiles('exportcat')}<p class="privacy-note">${t('市内交通 / 市外交通 / 餐补 / 办公用品 / 客户招待')}</p>`;return;}
 const rows=exportRows(),chosen=rows.filter(r=>S.selected.has(r.id));
 $('main').innerHTML=`<button class="back-link" id="exportBack">${icon('back')}${t('重新选择费用种类')}</button><span class="step">${t('02 / 选择日期和发票')}</span><h1 class="page-heading" style="font-size:24px">${esc(catName(S.exportCategory))}</h1><p class="page-sub">${t('只导出此类别，日期包含开始日与结束日')}</p><div class="panel"><div class="fields-row"><label class="field"><span>${t('开始日期')}</span><input type="date" id="exportFrom" value="${S.from}"></label><label class="field"><span>${t('结束日期')}</span><input type="date" id="exportTo" value="${S.to}"></label></div><div class="filter-pills" style="padding-bottom:0"><button class="pill" id="thisMonth">${t('本月')}</button><button class="pill" id="lastMonth">${t('上月')}</button><button class="pill" id="allDates">${t('全部日期')}</button></div></div><div class="section-title"><h2 style="font-size:16px">${t('选择要导出的发票')}</h2><button class="subtle-link" id="toggleAll">${t(rows.length&&chosen.length===rows.length?'取消全选':'全选')}</button></div>${exportBudget(chosen)}${exportNamesHint(S.exportCategory,S.from,S.to)}${rows.length?rows.map(r=>receiptCard(r,true)).join(''):empty(t('这段日期没有此类别的发票'))}<div class="export-fixed"><div class="summary-strip"><small>${t('已选择 {n} 张发票',{n:chosen.length})}</small><strong>${sum(chosen)}</strong></div><button class="primary" id="generateExport" ${chosen.length?'':'disabled'}>${icon('export')}${t('生成 PDF + Excel')}</button></div><p class="privacy-note">${t('按费用日期排序 · 汇总表包含对应的 PDF 页码<br>合并PDF为可视页面，原始图片/PDF保留在手机中')}</p>`;
}
function chooseExport(i){S.exportCategory=C[i];const rows=S.receipts.filter(r=>r.category===S.exportCategory).sort((a,b)=>a.date.localeCompare(b.date));S.from=rows[0]?.date||today().slice(0,7)+'-01';S.to=rows.at(-1)?.date||today();exportChanged();}
function datePreset(delta,all=false){if(all){const r=S.receipts.filter(r=>r.category===S.exportCategory).sort((a,b)=>a.date.localeCompare(b.date));S.from=r[0]?.date||today();S.to=r.at(-1)?.date||today();}else{const [y,m]=today().split('-').map(Number),d=new Date(y,m-1+delta,1);S.from=P.iso(d.getFullYear(),d.getMonth()+1,1);S.to=P.iso(d.getFullYear(),d.getMonth()+1,new Date(d.getFullYear(),d.getMonth()+1,0).getDate());}exportChanged();}
function renderArchive(){const rows=S.receipts.filter(r=>r.archivedAt),trash=S.trash||[];$('main').innerHTML=`<h1 class="page-heading">${t('归档与回收站')}</h1><p class="page-sub">${t('归档票据仍在日常列表，可再次导出。<br>只有从此页删除才进入 30 天回收站。')}</p><h2>${t('已归档 · {n} 张',{n:rows.length})}</h2>${rows.map(r=>receiptCard(r)+`<div class="button-row archive-actions"><button class="secondary" data-lifecycle="unarchive" data-id="${esc(r.id)}">${t('取消归档')}</button><button class="danger" data-lifecycle="trash" data-id="${esc(r.id)}">${t('删除至回收站')}</button></div>`).join('')||empty(t('暂无归档发票，导出成功后可选择归档'))}<h2>${t('回收站 · {n} 张',{n:trash.length})}</h2><p class="page-sub">${t('删除后 30 天内可恢复。到期后在启动或运行期间自动清理本机信息与原件；已导出的文件保留。')}</p>${trash.map(r=>`<div class="panel"><strong>${esc(r.merchant)} · ${amount(r.amountMinor,r.currency)}</strong><p>${esc(I18N.fmtDate(lang(),r.date))} · ${esc(catName(r.category))}</p><p>${t('到期时间：{time}',{time:esc(I18N.dateTime(lang(),r.deletedAt+30*86400000))})}</p><button class="secondary" data-lifecycle="recover" data-id="${esc(r.id)}">${t('恢复到归档区')}</button></div>`).join('')||empty(t('回收站为空'))}`;}
function showSettings(){const s=S.settings;modal(t('设置与说明'),`<div class="settings-list"><label class="field"><span>${t('语言 / Language')}</span><select id="settingLanguage"><option value="zh" ${s.language==='zh'?'selected':''}>中文</option><option value="en" ${s.language==='en'?'selected':''}>English</option></select></label><label class="field"><span>${t('货币')}</span><select id="settingCurrency">${P.CURRENCIES.map(c=>`<option value="${c}" ${s.currency===c?'selected':''}>${t(c==='GBP'?'英镑 GBP（£）':'欧元 EUR（€）')}</option>`).join('')}</select></label><p>${t('新发票和识别结果按这里的货币处理；落在出差日的发票按出差国家的货币处理。已保存的发票保留自己的货币，不做汇率换算。选择欧元时不显示市内交通的月度额度；餐补额度按出差国家计算。')}</p><p><strong>${t('随手报账 · 0.3.0')}</strong>${S.demo?t(' · 界面演示'):''}</p><p><strong>${t('拍照与识别')}</strong><br>${t('先选费用来源，再拍照或导入文件。建议平放发票，保证文字清楚。可批量导入多个文件并逐张核对；一张记录对应一张发票，多页可追加。原件在软件内查看，可翻页、缩放和旋转。PDF 识别前 3 页，导出保留所有页的可视内容。')}</p><p><strong>${t('你的日历')}</strong><br>${t('绿色出差、红色办公、蓝色休假。点击日期看当天发票，点击“标记日期”可设置一段时间。')}</p><p><strong>${t('按来源导出')}</strong><br>${t('先选五类费用之一，再选日期和具体发票。输出 PDF 合集、Excel 明细和分类合计，不同货币分别合计。')}</p><p><strong>${t('原件保存在本机')}</strong><br>${t('卸载或清除应用数据会删除发票。建议定期导出原件备份。备份 ZIP 包含原始文件、明细和日历状态，当前版本暂未提供一键恢复。')}</p><button class="primary" id="backupButton">${icon('folder')}${t('导出全部原件备份（ZIP）')}</button><p>${t('不需要注册账号。识别在手机上进行。识别结果为候选值，保存前请人工核对。')}</p></div>`,'settings');}
function applySettings(){I18N.localizeStatic(document,lang());$('toast').classList.add('hidden');if(S.demo)document.querySelector('.brand small').textContent=t('界面预览 · 使用模拟数据');}
window.onNative=function(event){
 if(event.type==='maintenance'){S.trash=event.data.receipts.filter(r=>r.deletedAt);S.receipts=event.data.receipts.filter(r=>!r.deletedAt);S.selected=new Set([...S.selected].filter(id=>S.receipts.some(r=>r.id===id)));if(!S.modal&&!S.busy)render();return;}
 if(event.type==='busy'){busy(event.data);return;}idle();
 switch(event.type){
 case 'preview':showPreview(event.data);break;
 case 'settings':{const v=event.data.settings;S.settings={language:v.language==='en'?'en':'zh',currency:P.normalizeCurrency(v.currency)};S.draft=event.data.draft;applySettings();render();if(S.modal==='settings')showSettings();break;}
 case 'data':S.trash=event.data.receipts.filter(r=>r.deletedAt);S.receipts=event.data.receipts.filter(r=>!r.deletedAt);S.days=event.data.days;S.countries=event.data.countries||S.countries||{};S.selected=new Set([...S.selected].filter(id=>S.receipts.some(r=>r.id===id)));S.draft=event.data.draft;if(S.preserveExport){S.preserveExport=false;if($('archivePrompt'))$('archivePrompt').innerHTML=t('本次导出的发票已归档，仍可保存或分享下面的文件。');}else hideModal();render();if(S.draft?.batchTotal&&!S.draft.needsScan){S.warnings=S.draft.scanMessage?[S.draft.scanMessage]:[];S.parsed=null;showEditor();}break;
 case 'draft':S.draft=event.data;if(typeof SmartScan!=='undefined'){SmartScan.reset();S.userEdited={date:true,amount:true,merchant:true};}showEditor();break;
 case 'scan':{
   S.draft=event.data.draft;S.warnings=[];
   if(event.data.first){if(typeof SmartScan!=='undefined')SmartScan.reset();S.parsed=P.parse(event.data.text,{currency:draftCurrency(S.draft)});const tripCurrency=!S.draft.id&&P.tripCurrencyOn(S.draft.date||S.parsed.date,S.days,S.countries);if(tripCurrency&&tripCurrency!==draftCurrency(S.draft)){S.draft.currency=tripCurrency;S.parsed=P.parse(event.data.text,{currency:tripCurrency});}S.mlkitParsed=S.parsed;S.warnings.push(...S.parsed.warnings);for(const k of ['date','amount','merchant'])if(!S.draft[k]&&S.parsed[k])S.draft[k]=k==='merchant'?P.merchantLabel(S.parsed[k],lang()):S.parsed[k];}
   else S.parsed=null;
   if(event.data.duplicate)S.warnings.push('这个原件已导入过，请确认是否重复报账');
   if(event.data.message)S.warnings.push(event.data.message);
   if(S.draft.documents.some(d=>d.pages>1))S.warnings.push('多页PDF请确认只包含一张发票；多张不同发票请分别导入');
   showEditor();persistFields();S.extraWarnings=S.warnings.filter(w=>!(S.parsed?.warnings||[]).includes(w));if(event.data.first&&typeof SmartScan!=='undefined'&&SmartScan.isImage(S.draft.documents[0]))SmartScan.run(0);break;
 }
 case 'cancel':call('ready');break;
 case 'toast':toast(S.lastSave&&String(event.data).includes('发票已保存')?savedMessage(event.data,S.lastSave):tr(event.data));if(String(event.data).includes('发票已保存'))S.lastSave=null;break;
 case 'error':S.preserveExport=false;if(typeof event.data==='object'){toast(tr(event.data.message));S.draft=event.data.draft;}else toast(tr(event.data));if(S.draft&&S.modal!=='editor')showEditor();break;
 case 'exported':modal(t('文件已生成'),`<div class="notice">${t(event.data.length===2?'发票合集和报账汇总表已生成。请保存或分享这两个文件。':'原始发票、明细和日历标记已打包。请保存备份文件。')}</div>${event.data.map(n=>`<div class="file-ready">${icon(n.endsWith('.pdf')?'receipt':'folder')}<span>${esc(n)}</span></div>`).join('')}${event.data.length===2?`<div class="notice" id="archivePrompt"><strong>${t('是否归档本次导出的发票？')}</strong><p>${t('仅增加归档标记，原件、日常列表和餐补统计仍保留。')}</p><div class="button-row"><button class="secondary" id="archiveExport">${t('归档')}</button><button class="secondary" id="skipArchive">${t('暂不归档')}</button></div></div>`:''}<button class="primary" id="saveFiles">${t('保存到手机文件夹')}</button><div class="button-row"><button class="secondary" id="shareFiles">${t('分享文件')}</button></div>`,'exported');break;
 case 'savedFiles':toast(t('已保存：{names}',{names:event.data.join(t('、'))}));break;
 }
};
document.addEventListener('click',e=>{
 const button=e.target.closest('button'),el=e.target.closest('[data-receipt],[data-toggle]');
 if(S.busy)return;
 if(e.target.dataset.checkbox){S.selected.has(e.target.dataset.checkbox)?S.selected.delete(e.target.dataset.checkbox):S.selected.add(e.target.dataset.checkbox);renderExport();return;}
 if(el&&el.dataset.receipt){showDetail(el.dataset.receipt);return;}
 if(el&&el.dataset.toggle){const id=el.dataset.toggle;S.selected.has(id)?S.selected.delete(id):S.selected.add(id);renderExport();return;}
 if(!button)return;const d=button.dataset;
 if(d.tab){S.tab=d.tab;render();window.scrollTo(0,0);return;}
 if(d.day){S.selectedDay=d.day;renderCalendar();document.querySelectorAll('#main .section-title')[1]?.scrollIntoView({block:'start',behavior:'smooth'});return;}
 if(d.choose!==undefined){S.newCategory=C[+d.choose];$('newCats').innerHTML=categoryTiles('choose');$('captureNew').disabled=false;$('importNew').disabled=false;return;}
 if(d.exportcat!==undefined){chooseExport(+d.exportcat);return;}
 if(d.listcat!==undefined){S.listCategory=d.listcat==='all'?'all':C[+d.listcat];renderReceipts();return;}
 if(d.edit){hideModal();S.warnings=[];S.parsed=null;busy(t('正在打开发票…'));call('edit',d.edit);return;}
 if(d.delete){if(confirm(t('删除这张发票及其原件？此操作无法撤销。'))){hideModal();busy(t('正在删除…'));call('delete',d.delete);}return;}
 if(d.lifecycle){if(d.lifecycle==='trash'&&!confirm(t('移入回收站？信息与原件保留 30 天，期间可以恢复，到期自动清理。')))return;busy(t('正在更新归档…'));call('lifecycle',d.id,d.lifecycle);return;}
 if(d.open!==undefined){if(S.modal==='editor')persistFields();call('open',d.owner,+d.open);return;}
 if(d.remove!==undefined){if(confirm(t('移除这个附件？'))){persistFields();busy(t('正在移除附件…'));call('removeAttachment',+d.remove);}return;}
 if(d.datecandidate){$('editDate').value=d.datecandidate;$('editConfirmed').checked=false;persistFields();followTrip();return;}
 if(d.amountcandidate){$('editAmount').value=d.amountcandidate;persistFields();return;}
 if(d.mealmerchant){$('editMerchant').value=d.mealmerchant;$('editConfirmed').checked=false;persistFields();return;}
 switch(button.id){
 case 'archiveExport':S.preserveExport=true;busy(t('正在归档…'));call('archiveExport');break;
 case 'skipArchive':$('archivePrompt').remove();break;
 case 'settingsButton':showSettings();break;
 case 'closeModal':closeModal();break;
 case 'prevMonth':monthChange(-1);break;case 'nextMonth':monthChange(1);break;
 case 'markDay':showMark();break;
 case 'saveMark':{const f=$('markFrom').value,to=$('markTo').value;if(!P.validDate(f)||!P.validDate(to)||to<f)return toast(t('请选择有效的日期范围'));busy(t('正在更新日历…'));call('markDays',f,to,$('markType').value,$('markType').value==='business'?$('markCountry').value:'');break;}
 case 'addReceipt':case 'addForDay':showNew();break;
 case 'resumeDraft':S.warnings=[];S.parsed=null;showEditor();break;
 case 'captureNew':startCapture('capture',false);break;case 'importNew':startCapture('importFile',false);break;
 case 'appendCamera':startCapture('capture',true);break;case 'appendFile':startCapture('importFile',true);break;
 case 'saveReceipt':{const f=fieldData();if(!P.validDate(f.date))return toast(t('请填写有效的完整日期'));try{P.minor(f.amount);}catch(err){return toast(tr(err.message));}if(!f.merchant)return toast(t('请填写商家或交通运营方'));if(!f.confirmed)return toast(t('请勾选已核对发票信息'));if(!S.draft.documents.length)return toast(t('请添加至少一个发票附件'));const duplicates=P.receiptDuplicates({...S.draft,...f},S.receipts);if((duplicates.matches.length||duplicates.repeatedAttachments)&&!confirm(t('检测到重复原件或疑似重复发票，请核对已有记录。仍要保存这张发票吗？')))return;S.lastSave={category:f.category,date:f.date,currency:f.currency};busy(t('正在保存发票…'));call('save',JSON.stringify(f));break;}
 case 'discardDraft':if(confirm(t('放弃当前这张草稿？本张未保存的新附件将被移除，本批其余票据保留并继续核对。'))){busy(t('正在放弃草稿…'));call('discardDraft');}break;
 case 'exportBack':S.exportCategory=null;S.selected.clear();renderExport();break;
 case 'thisMonth':datePreset(0);break;case 'lastMonth':datePreset(-1);break;case 'allDates':datePreset(0,true);break;
 case 'toggleAll':{const rows=exportRows();S.selected=rows.length&&rows.every(r=>S.selected.has(r.id))?new Set():new Set(rows.map(r=>r.id));renderExport();break;}
 case 'generateExport':if(!P.validDate(S.from)||!P.validDate(S.to)||S.to<S.from)return toast(t('请选择有效的日期范围'));busy(t('正在生成发票 PDF 和 Excel…'));call('export',JSON.stringify({category:S.exportCategory,from:S.from,to:S.to,ids:[...S.selected]}));break;
 case 'saveFiles':call('saveExport');break;case 'shareFiles':call('shareExport');break;
 case 'backupButton':busy(t('正在打包原件备份…'));call('backup');break;
 }
});
document.addEventListener('change',e=>{if(e.target.id==='settingLanguage'||e.target.id==='settingCurrency'){call('setSettings',JSON.stringify({language:$('settingLanguage').value,currency:$('settingCurrency').value}));return;}if(e.target.id==='editCurrency'){Object.assign(S.draft,fieldData());reparseCurrency();showEditor();persistFields();return;}if(e.target.id==='markType'||e.target.id==='markCountry'){markTypeChanged();return;}if(e.target.id==='markTo'){markRangeChanged();return;}if(e.target.id==='markFrom'){if($('markDays').value)markDaysChanged();else markRangeChanged();return;}if(e.target.id==='editDate'){persistFields();followTrip();return;}if(e.target.id==='editCategory')$('mealMerchantChoices').classList.toggle('hidden',e.target.value!==C[2]);if(S.modal==='editor'&&e.target.id?.startsWith('edit'))persistFields();if(e.target.id==='exportFrom'||e.target.id==='exportTo'){S.from=$('exportFrom').value;S.to=$('exportTo').value;exportChanged();}});
document.addEventListener('input',e=>{if(e.target.id==='markDays'){markDaysChanged();return;}if(S.modal==='editor'&&e.target.id?.startsWith('edit'))updateEditorHints();if(e.target.id==='receiptSearch'){S.search=e.target.value;const pos=e.target.selectionStart;renderReceipts();$('receiptSearch').focus();$('receiptSearch').setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.key==='Enter'||e.key===' ')&&e.target.matches('article.receipt')){e.preventDefault();e.target.click();}});
window.handleBack=function(){if(S.viewer){closePreview();return;}if(S.busy)return;if(S.modal){closeModal();return;}if(S.tab==='export'&&S.exportCategory){S.exportCategory=null;render();return;}if(S.tab!=='calendar'){S.tab='calendar';render();return;}call('quit');};
$('brandIcon').innerHTML=icon('receipt');$('settingsButton').innerHTML=icon('settings');
// Browser-only preview uses clearly labelled synthetic records. Native Android starts empty.
function demoPreview(d){const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="220" height="300"><rect width="220" height="300" fill="white"/><text x="25" y="45" font-family="sans-serif" font-size="18" fill="#253a34">DEMO RECEIPT</text><text x="25" y="80" font-family="sans-serif" font-size="11" fill="#888">09/10/2026</text><path d="M25 100h170M25 130h150M25 155h165M25 180h110" stroke="#ddd"/><text x="25" y="235" font-family="sans-serif" font-size="17" fill="#253a34">TOTAL     £ 12.80</text><text x="25" y="275" font-family="sans-serif" font-size="10" fill="#888">UI DEMO / SAMPLE DATA</text></svg>`;return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);}
function demoLoad(){const saved=localStorage.getItem('baozhang-demo');if(saved){try{const data=JSON.parse(saved);S.trash=(data.receipts||[]).filter(r=>r.deletedAt&&Date.now()-r.deletedAt<30*86400000);S.receipts=(data.receipts||[]).filter(r=>!r.deletedAt);S.days=data.days;S.countries=data.countries||{};S.draft=data.draft||null;return;}catch(_){}}const base=today().slice(0,7);S.days={[base+'-05']:'business',[base+'-06']:'business',[base+'-07']:'office',[base+'-08']:'office',[base+'-09']:'business',[base+'-10']:'holiday',[base+'-11']:'holiday'};S.receipts=[['TfL · 地铁',690,C[0],'09'],['Tesco · 出差午餐',1280,C[2],'09'],['客户晚餐',4850,C[4],'05'],['Great Western Railway',3240,C[1],'05'],['Ryman · 办公用品',1599,C[3],'07']].map(([merchant,n,category,day],i)=>({id:'demo-'+i,date:base+'-'+day,merchant,location:'London',note:'界面演示数据',category,amountMinor:n,currency:'GBP',documents:[{name:'sample.jpg',mime:'image/jpeg',pages:1}]}));S.selectedDay=base+'-09';}
function demoSave(){localStorage.setItem('baozhang-demo',JSON.stringify({receipts:[...S.receipts,...(S.trash||[])],days:S.days,countries:S.countries||{},draft:S.draft}));}
function demoCall(method,...args){
 const emit=(type,data)=>window.onNative({type,data});
 if(method==='ready'){demoLoad();emit('data',{receipts:[...S.receipts,...(S.trash||[])],days:S.days,countries:S.countries||{},draft:S.draft});return;}
 if(method==='setSettings'){S.settings=JSON.parse(args[0]);try{localStorage.setItem('baozhang-settings',args[0]);}catch(_){}if(S.draft&&!S.draft.id){S.draft.currency=S.settings.currency;demoSave();}emit('settings',{settings:S.settings,draft:S.draft});return;}
 if(method==='capture'||method==='importFile'){const [cat,append]=args;if(!append)S.draft={category:cat,date:'',amount:'',merchant:'',location:'',note:'',ocr:'',documents:[]};S.draft.documents.push({name:'sample.jpg',mime:'image/jpeg',pages:1});const text='Tesco\nLondon\n09/10/2026\nSubtotal 10.67\nVAT 2.13\nTOTAL £12.80';S.draft.ocr=text;emit('scan',{draft:S.draft,text,first:!append,duplicate:false,message:'界面演示：这是模拟扫描结果，真实相机和识别需在安卓应用中使用。'});demoSave();return;}
 if(method==='updateDraft'){Object.assign(S.draft,JSON.parse(args[0]));demoSave();return;}
 if(method==='save'){const f=JSON.parse(args[0]);const id=S.draft.id||'demo-'+Date.now(),r={...S.draft,...f,id,amountMinor:P.minor(f.amount),currency:P.normalizeCurrency(f.currency)};S.receipts=S.receipts.filter(o=>o.id!==id);S.receipts.push(r);S.draft=null;demoSave();emit('data',{receipts:[...S.receipts,...(S.trash||[])],days:S.days,draft:null});emit('toast','演示发票已保存');return;}
 if(method==='edit'){S.draft={...S.receipts.find(r=>r.id===args[0])};S.draft.documents=JSON.parse(JSON.stringify(S.draft.documents));S.draft.amount=P.money(S.draft.amountMinor);emit('draft',S.draft);demoSave();return;}
 if(method==='discardDraft'){S.draft=null;demoSave();emit('data',{receipts:[...S.receipts,...(S.trash||[])],days:S.days,draft:null});return;}
 if(method==='removeAttachment'){S.draft.documents.splice(args[0],1);demoSave();emit('draft',S.draft);return;}
 if(method==='delete'){S.receipts=S.receipts.filter(r=>r.id!==args[0]);demoSave();emit('data',{receipts:[...S.receipts,...(S.trash||[])],days:S.days,draft:S.draft});return;}
 if(method==='markDays'){const [f,t,type,country]=args;S.countries=S.countries||{};if(type==='business'&&!P.TRIP_COUNTRIES.some(c=>c.code===country))return emit('error','出差国家无效');if(t<f)return emit('error','结束日期不能早于开始日期');const end=new Date(t+'T00:00:00Z'),date=new Date(f+'T00:00:00Z');if((end-date)/86400000>731)return emit('error','标记范围不能超过两年');while(date<=end){const key=date.toISOString().slice(0,10);if(type)S.days[key]=type;else delete S.days[key];if(type==='business')S.countries[key]=country;else delete S.countries[key];date.setUTCDate(date.getUTCDate()+1);}demoSave();emit('data',{receipts:[...S.receipts,...(S.trash||[])],days:S.days,draft:S.draft});return;}
 if(method==='lifecycle'){const rows=[...S.receipts,...(S.trash||[])],r=rows.find(r=>r.id===args[0]),action=args[1];if(!r)return emit('error','发票不存在');if(action==='trash'){if(!r.archivedAt)return emit('error','只能从归档区删除');r.deletedAt=r.deletedAt||Date.now();}else if(action==='recover'){if(Date.now()-r.deletedAt>=30*86400000)return emit('error','恢复期限已到');delete r.deletedAt;}else delete r.archivedAt;S.receipts=rows.filter(r=>!r.deletedAt);S.trash=rows.filter(r=>r.deletedAt);demoSave();emit('data',{receipts:rows,days:S.days,draft:S.draft});return;}
 if(method==='archiveExport'){for(const r of S.receipts)if(S.demoExportIds?.includes(r.id))r.archivedAt=r.archivedAt||Date.now();demoSave();emit('data',{receipts:[...S.receipts,...(S.trash||[])],days:S.days,draft:S.draft});return;}
 if(method==='export'||method==='backup')return emit('error','此文件仅用于界面预览。真实 PDF、Excel 与备份导出在安卓应用中执行。');
 if(method==='open'){const r=args[0]==='draft'?S.draft:S.receipts.find(r=>r.id===args[0]);emit('preview',r.documents[args[1]]);return;}
 if(method==='quit')return toast('这是浏览器预览，可直接关闭此页面');idle();
}
render();applySettings();call('ready');
